import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy_top():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                return True
        return False

    def clean_sell_top():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        # matching
        if side == 'buy':
            while remaining > 0 and clean_sell_top():
                top_price, top_seq, top_id = sell_heap[0]
                if typ != 'market' and price is not None and top_price > price:
                    break
                resting = orders_info[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    resting['active'] = False
                # else keep at top, position unchanged (price,seq same), loop will re-check top next iter with same qty updated
        else:  # side == 'sell'
            while remaining > 0 and clean_buy_top():
                negprice, top_seq, top_id = buy_heap[0]
                top_price = -negprice
                if typ != 'market' and price is not None and top_price < price:
                    break
                resting = orders_info[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    resting['active'] = False

        if typ == 'limit' and remaining > 0:
            seq_counter += 1
            info = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
            orders_info[oid] = info
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
        elif typ == 'limit' and remaining == 0:
            # fully filled immediately, still register as filled/inactive for cancel purposes
            orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': None, 'active': False}
        # ioc/market remainder discarded, but still record as inactive if partially/fully done
        else:
            orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False, 'seq': None}

    return trades

